40:     // constructor, setup event listeners and external interfaces
41:     public function ZeroClipboard() {
42: 
43:       // Align the stage to top left
44:       stage.align = "TL";
45:       stage.scaleMode = "noScale";
46: 
47:       // Get the flashvars
48:       var flashvars:Object = LoaderInfo( this.root.loaderInfo ).parameters;
