50:       // Allow the SWF object to communicate with a page on a different origin than its own (e.g. SWF served from CDN)
51:       if (flashvars.trustedOrigins && typeof flashvars.trustedOrigins === "string") {
52:         var origins:Array = flashvars.trustedOrigins.split("\\").join("\\\\").split(",");
53:         flash.system.Security.allowDomain.apply(null, origins);
54:       }
55: 
56:       // Enable complete AMD (e.g. RequireJS) and CommonJS (e.g. Browserify) support
57:       if (flashvars.jsModuleId && typeof flashvars.jsModuleId === "string") {
58:         jsModuleId = flashvars.jsModuleId.split("\\").join("\\\\");
59:       }
60: 
61:       // invisible button covers entire stage
62:       button = new Sprite();
63:       button.buttonMode = true;
64:       button.useHandCursor = false;
65:       button.graphics.beginFill(0xCCFF00);
66:       button.graphics.drawRect(0, 0, stage.stageWidth, stage.stageHeight);
67:       button.alpha = 0.0;
68:       addChild(button);
69: 
70:       // Adding the event listeners
71:       button.addEventListener(MouseEvent.CLICK, mouseClick);
72:       button.addEventListener(MouseEvent.MOUSE_OVER, mouseOver);
73:       button.addEventListener(MouseEvent.MOUSE_OUT, mouseOut);
74:       button.addEventListener(MouseEvent.MOUSE_DOWN, mouseDown);
75:       button.addEventListener(MouseEvent.MOUSE_UP, mouseUp);
76: 
77:       // external functions
78:       ExternalInterface.addCallback("setHandCursor", setHandCursor);
79:       ExternalInterface.addCallback("setText", setText);
80:       ExternalInterface.addCallback("setSize", setSize);
81: 
82:       // signal to the browser that we are ready
83:       dispatch("load", ZeroClipboard.metaData());
84:     }
85: 
86:     // mouseClick
87:     //
88:     // The mouseClick private function handles clearing the clipboard, and
89:     // setting new clip text. It gets this from the clipText private variable.
90:     // Once the text has been placed in the clipboard, It then signals to the
91:     // Javascript that it is done.
92:     //
93:     // returns nothing
94:     private function mouseClick(event:MouseEvent): void {
95: 
96:       // Linux currently doesn't use the correct clipboard buffer with the new
97:       // Flash 10 API, so we need to use this until we can figure out an alternative
98:       flash.system.System.setClipboard(clipText);
99: 
100:       // signal to the page it is done
101:       dispatch("complete", ZeroClipboard.metaData(event, {
102:         text: clipText.split("\\").join("\\\\")
103:       }));
104: 
105:       // reset the text
106:       clipText = "";
107:     }
108: 
109:     // mouseOver
110:     //
111:     // The mouseOver function signals to the page that the button is being hovered.
112:     //
113:     // returns nothing
114:     private function mouseOver(event:MouseEvent): void {
115:       dispatch("mouseOver", ZeroClipboard.metaData(event));
116:     }
117: 
118:     // mouseOut
119:     //
120:     // The mouseOut function signals to the page that the button is not being hovered.
121:     //
122:     // returns nothing
123:     private function mouseOut(event:MouseEvent): void {
124:       dispatch("mouseOut", ZeroClipboard.metaData(event));
125:     }
126: 
127:     // mouseDown
128:     //
129:     // The mouseDown function signals to the page that the button has a mouse button down.
130:     //
131:     // returns nothing
132:     private function mouseDown(event:MouseEvent): void {
133:       dispatch("mouseDown", ZeroClipboard.metaData(event));
134: 
135:       // if the clipText hasn't been set
136:       if (!clipText) {
137:         // request data from the page
138:         dispatch("dataRequested", ZeroClipboard.metaData(event));
139:       }
140:     }
141: 
142:     // mouseUp
143:     //
144:     // The mouseUp function signals to the page that the mouse button has been lifted
145:     //
146:     // returns nothing
147:     private function mouseUp(event:MouseEvent): void {
148:       dispatch("mouseUp", ZeroClipboard.metaData(event));
149:     }
150: 
151:     // setText
152:     //
153:     // setText gets the clipboard text to be copied from the javascript.
154:     //
155:     // returns nothing
156:     public function setText(newText:String): void {
157:       // set the maximum number of files allowed
158:       clipText = newText;
159:     }
160: 
161:     // setHandCursor
162:     //
163:     // setHandCursor will make the button cursor be a hand on hover.
164:     //
165:     // returns nothing
166:     public function setHandCursor(enabled:Boolean): void {
167:       button.useHandCursor = enabled;
168:     }
169: 
170:     // setSize
171:     //
172:     // Sets the size of the button to equal the size of the hovered object.
173:     //
174:     // returns nothing
175:     public function setSize(width:Number, height:Number): void {
176:       button.width = width;
177:       button.height = height;
178:     }
179: 
180:     // dispatch
181:     //
182:     // Function through which JavaScript events are dispatched
183:     //
184:     // returns nothing
185:     private function dispatch(eventName:String, eventArgs:Object): void {
186:       if (jsModuleId) {
187:         ExternalInterface.call(ZeroClipboard.JS_MODULE_WRAPPED_DISPATCHER, eventName, eventArgs, jsModuleId);
188:       }
189:       else {
190:         ExternalInterface.call(ZeroClipboard.NORMAL_DISPATCHER, eventName, eventArgs);
191:       }
192:     }
193: 
194:     // metaData
195:     //
196:     // The metaData function will take a mouseEvent, and an extra object to
197:     // create a meta object of more info. This will let the page know if
198:     // certain modifier keys are down
199:     //
200:     // returns an Object of extra event data
201:     private static function metaData(event:MouseEvent = void, extra:Object = void):Object {
202: 
203:       // create the default options, contains flash version
204:       var normalOptions:Object = {
205:         flashVersion: Capabilities.version
206:       };
207: 
208:       // if an event is passed in, return what modifier keys are pressed
209:       if (event) {
210:         normalOptions.altKey = event.altKey;
211:         normalOptions.ctrlKey = event.ctrlKey;
212:         normalOptions.shiftKey = event.shiftKey;
213:       }
214: 
215:       // for everything in the extra object, add it to the normal options
216:       for (var i:String in extra) {
217:         normalOptions[i] = extra[i];
218:       }
219: 
220:       return normalOptions;
221:     }
222:   }
223: }"
